from execution_status_dashboard import PREVIOUS_EXECUTION_BANNER, PREVIOUS_VERIFIED_EXECUTION_BANNER, PREVIOUS_PRICE_EXECUTION_BANNER, render_current_banner

CURRENT_BANNER = render_current_banner()


def strip_banner(html: str) -> str:
    """Remove only the exact current wrapper to recover prior archive bytes."""
    if 'id="v12-current-evidence"' not in html:
        return html
    matches = [banner for banner in (CURRENT_BANNER, PREVIOUS_PRICE_EXECUTION_BANNER, PREVIOUS_VERIFIED_EXECUTION_BANNER, PREVIOUS_EXECUTION_BANNER, R19_BANNER, R17_POPULATION_BANNER, R17_CHECKPOINT_BANNER, R16_BANNER, R15_BANNER, PREVIOUS_BANNER) if html.count(banner) == 1]
    if len(matches) != 1:
        raise ValueError('Unexpected current evidence banner')
    return html.replace(matches[0], '', 1)


def render_banner(html: str) -> str:
    """Compose the current link without modifying dated historical content."""
    html = strip_banner(html)
    if html.count('<main>') != 1:
        raise ValueError('Historical landing must have one main element')
    return html.replace('<main>', '<main>' + CURRENT_BANNER, 1)
